Here is the commit message:
drm/virtio: Fix return value for
 VIRTGPU_CONTEXT_PARAM_DEBUG_NAME

The strncpy_from_user() returns number of copied bytes and not zero on
success. The non-zero return value of ioctl is treated as error. Return
zero on success instead of the number of copied bytes.

Fixes: 7add80126bce ("drm/uapi: add explicit virtgpu context debug name")
Signed-off-by: Dmitry Osipenko <dmitry.osipenko@collabora.com>
Reviewed-by: Gurchetan Singh <gurchetansingh@chromium.org>
Link: https://patchwork.freedesktop.org/patch/msgid/20231111224236.890431-1-dmitry.osipenko@collabora.com

Here is the root cause:
The bug was caused by the `virtio_gpu_context_init_ioctl` function returning the number of bytes copied by `strncpy_from_user()` instead of returning zero on success. This non-zero return value was incorrectly interpreted as an error by the ioctl interface, leading to unintended error handling in the system.

Here is the patch:

 static int virtio_gpu_context_init_ioctl(struct drm_device *dev,
 					 void *data, struct drm_file *file)
 {
 	int ret = 0;
 	uint32_t num_params, i;
 	uint64_t valid_ring_mask, param, value;
 	size_t len;
 	struct drm_virtgpu_context_set_param *ctx_set_params = NULL;
 	struct virtio_gpu_device *vgdev = dev->dev_private;
 	struct virtio_gpu_fpriv *vfpriv = file->driver_priv;
 	struct drm_virtgpu_context_init *args = data;

 	num_params = args->num_params;
 	len = num_params * sizeof(struct drm_virtgpu_context_set_param);

 	if (!vgdev->has_context_init || !vgdev->has_virgl_3d)
 		return -EINVAL;

 	/* Number of unique parameters supported at this time. */
 	if (num_params > 4)
 		return -EINVAL;

 	ctx_set_params = memdup_user(u64_to_user_ptr(args->ctx_set_params),
 				     len);

 	if (IS_ERR(ctx_set_params))
 		return PTR_ERR(ctx_set_params);

 	mutex_lock(&vfpriv->context_lock);
 	if (vfpriv->context_created) {
 		ret = -EEXIST;
 		goto out_unlock;
 	}

 	for (i = 0; i < num_params; i++) {
 		param = ctx_set_params[i].param;
 		value = ctx_set_params[i].value;

 		switch (param) {
 		case VIRTGPU_CONTEXT_PARAM_CAPSET_ID:
 			if (value > MAX_CAPSET_ID) {
 				ret = -EINVAL;
 				goto out_unlock;
 			}

 			if ((vgdev->capset_id_mask & (1ULL << value)) == 0) {
 				ret = -EINVAL;
 				goto out_unlock;
 			}

 			/* Context capset ID already set */
 			if (vfpriv->context_init &
 			    VIRTIO_GPU_CONTEXT_INIT_CAPSET_ID_MASK) {
 				ret = -EINVAL;
 				goto out_unlock;
 			}

 			vfpriv->context_init |= value;
 			break;
 		case VIRTGPU_CONTEXT_PARAM_NUM_RINGS:
 			if (vfpriv->base_fence_ctx) {
 				ret = -EINVAL;
 				goto out_unlock;
 			}

 			if (value > MAX_RINGS) {
 				ret = -EINVAL;
 				goto out_unlock;
 			}

 			vfpriv->base_fence_ctx = dma_fence_context_alloc(value);
 			vfpriv->num_rings = value;
 			break;
 		case VIRTGPU_CONTEXT_PARAM_POLL_RINGS_MASK:
 			if (vfpriv->ring_idx_mask) {
 				ret = -EINVAL;
 				goto out_unlock;
 			}

 			vfpriv->ring_idx_mask = value;
 			break;
 		case VIRTGPU_CONTEXT_PARAM_DEBUG_NAME:
 			if (vfpriv->explicit_debug_name) {
 				ret = -EINVAL;
 				goto out_unlock;
 			}

 			ret = strncpy_from_user(vfpriv->debug_name,
 						u64_to_user_ptr(value),
 						DEBUG_NAME_MAX_LEN - 1);
 			if (ret < 0)
 				goto out_unlock;

 			vfpriv->explicit_debug_name = true;
+			ret = 0;
 			break;
 		default:
 			ret = -EINVAL;
 			goto out_unlock;
 		}
 	}

 	if (vfpriv->ring_idx_mask) {
 		valid_ring_mask = 0;
 		for (i = 0; i < vfpriv->num_rings; i++)
 			valid_ring_mask |= 1ULL << i;

 		if (~valid_ring_mask & vfpriv->ring_idx_mask) {
 			ret = -EINVAL;
 			goto out_unlock;
 		}
 	}

 	virtio_gpu_create_context_locked(vgdev, vfpriv);
 	virtio_gpu_notify(vgdev);

 out_unlock:
 	mutex_unlock(&vfpriv->context_lock);
 	kfree(ctx_set_params);
 	return ret;
 }



